    vocabulary: [["Monument","(Noun) A structure commemorating a person or event."],["Plinth","(Noun) The base on which a statue stands."],["Glorification","(Noun) Praise that exaggerates worth or virtue."],["Context panel","(Noun) Signage explaining background and critique."],["Anti-monument","(Noun) A work that resists traditional heroic commemoration."],["Temporal","(Adjective) Related to time; not permanent."],["Pedestal","(Noun) A raised platform supporting a statue."],["Heritage protection","(Noun) Laws restricting alteration of historic sites."],["Legitimacy","(Noun) Accepted rightness or authority."],["Virality","(Noun) Rapid spread through public attention."],["Aftermath","(Noun) The consequences following a major event."],["Insult","(Noun) An act that shows disrespect or harm."],["Commemoration","(Noun) An act of remembering and honouring."],["Relocation","(Noun) Moving something to a different place."],["Frozen","(Adjective) Fixed; unable to change."],["Organiser","(Noun) A person who coordinates collective action."]],
