    vocabulary: [["Patrimony","(Noun) Cultural heritage belonging to a people."],["Restitution","(Noun) Return of wrongfully taken property."],["Stewardship","(Noun) Responsible care of something entrusted to one."],["Expropriate","(Verb) To take property for public use, often with compensation."],["Externality","(Noun) A cost or benefit affecting others not involved in a transaction."],["Due process","(Noun) Fair legal procedures before rights are removed."],["Confiscation","(Noun) Forced taking of property by authority."],["Loot","(Noun) Goods taken by force or in war."],["Threshold","(Noun) A point at which a rule or action begins."],["Tribunal","(Noun) A body judging disputes or claims."],["Arbitrary","(Adjective) Based on random will rather than rule."],["Heir","(Noun) A person legally entitled to inherit property."],["Acquisition","(Noun) The act of obtaining something."],["Concealment","(Noun) The act of hiding something."],["Inheritance","(Noun) Something received from those who came before."],["Ad hoc","(Adjective) Created for a specific case without general planning."]],
