    vocabulary: [["Literalism","(Noun) Strict adherence to exact words."],["Register","(Noun) Level of formality and style in language."],["Domesticate","(Verb) To adapt something to seem native, sometimes flattening difference."],["Exoticise","(Verb) To portray as foreign in a stereotyped way."],["Equivalence","(Noun) Correspondence in meaning or effect."],["Glossary","(Noun) A list of terms with explanations."],["Idiom","(Noun) A phrase whose meaning is not literal."],["Arbitrate","(Verb) To judge and decide between options."],["Nuance","(Noun) A subtle difference in meaning or tone."],["Absolution","(Noun) Release from blame or guilt."],["Palatable","(Adjective) Acceptable or pleasant to taste (figurative: agreeable)."],["Afterword","(Noun) A concluding section added by author or translator."],["Semantic","(Adjective) Relating to meaning in language."],["Vandalism","(Noun) Deliberate destruction; here, reckless rewriting."],["Constraint","(Noun) A limit that shapes what is possible."],["Fluency","(Noun) Smooth, natural flow of language."]],
